/* ============================================================
   BÖLÜM 5: Veri Türü Optimizasyonu
   ============================================================ */
+ '<h2 class="l-title">5. Veri Türü Optimizasyonu</h2>'

+ '<div class="calc-highlight"><strong>Yukleme sonrasi bile bellegi %60-90 azaltabilirsiniz.</strong> Pandas varsayilan olarak en büyük turleri (int64, float64, object) kullanir. Cogu gerçek veri daha küçük turlere rahatca sigar. Bu bolum dort temel teknik gösterir: category dtype, numerik kucultme, seyrek diziler ve string turu.</div>'

+ '<p class="l-text"><strong>Teknik 1: Category dtype</strong> -- az sayida benzersiz degere (düşük kardinalite) sahip sutunlar için:</p>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">import</span> pandas <span class="kw">as</span> pd\n<span class="kw">import</span> numpy <span class="kw">as</span> np\n\n<span class="cm"># 1M satirlik bir veri kumesi simule et</span>\nnp.random.<span class="fn">seed</span>(<span class="num">42</span>)\nn = <span class="num">1_000_000</span>\ndf = pd.<span class="fn">DataFrame</span>({\n    <span class="str">"ulke"</span>: np.random.<span class="fn">choice</span>([<span class="str">"TR"</span>, <span class="str">"US"</span>, <span class="str">"DE"</span>, <span class="str">"FR"</span>, <span class="str">"JP"</span>], n),\n    <span class="str">"durum"</span>: np.random.<span class="fn">choice</span>([<span class="str">"aktif"</span>, <span class="str">"pasif"</span>, <span class="str">"beklemede"</span>], n),\n    <span class="str">"fiyat"</span>: np.random.<span class="fn">uniform</span>(<span class="num">1</span>, <span class="num">1000</span>, n),\n    <span class="str">"miktar"</span>: np.random.<span class="fn">randint</span>(<span class="num">1</span>, <span class="num">100</span>, n)\n})\n\n<span class="cm"># Optimizasyon oncesi</span>\n<span class="fn">print</span>(<span class="str">"Once:"</span>, df.<span class="fn">memory_usage</span>(deep=<span class="kw">True</span>).<span class="fn">sum</span>() / <span class="num">1e6</span>, <span class="str">"MB"</span>)\n<span class="cm"># ~130 MB</span>\n\n<span class="cm"># Düşük kardinalite metinleri category\'ye dönüştür</span>\ndf[<span class="str">"ulke"</span>] = df[<span class="str">"ulke"</span>].<span class="fn">astype</span>(<span class="str">"category"</span>)\ndf[<span class="str">"durum"</span>] = df[<span class="str">"durum"</span>].<span class="fn">astype</span>(<span class="str">"category"</span>)\n\n<span class="cm"># Numerikleri kucult</span>\ndf[<span class="str">"fiyat"</span>] = pd.<span class="fn">to_numeric</span>(df[<span class="str">"fiyat"</span>], downcast=<span class="str">"float"</span>)  <span class="cm"># float64 -> float32</span>\ndf[<span class="str">"miktar"</span>] = pd.<span class="fn">to_numeric</span>(df[<span class="str">"miktar"</span>], downcast=<span class="str">"integer"</span>)  <span class="cm"># int64 -> int8</span>\n\n<span class="cm"># Optimizasyon sonrasi</span>\n<span class="fn">print</span>(<span class="str">"Sonra:"</span>, df.<span class="fn">memory_usage</span>(deep=<span class="kw">True</span>).<span class="fn">sum</span>() / <span class="num">1e6</span>, <span class="str">"MB"</span>)\n<span class="cm"># ~7 MB -- %95 azalma!</span></code></pre></div>'

+ '<p class="l-text"><strong>Teknik 2: Otomatik optimizasyon fonksiyonu</strong> -- herhangi bir DataFrame\'e uygulayin:</p>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">def</span> <span class="fn">dtype_optimize_et</span>(df, kat_esik=<span class="num">0.05</span>):\n    <span class="str">"""DataFrame bellegini dtype optimizasyonu ile azalt."""</span>\n    <span class="kw">for</span> sut <span class="kw">in</span> df.columns:\n        sut_tur = df[sut].dtype\n        \n        <span class="kw">if</span> sut_tur == <span class="str">"object"</span>:\n            <span class="cm"># Az benzersiz değer varsa category\'ye dönüştür</span>\n            oran = df[sut].<span class="fn">nunique</span>() / <span class="fn">len</span>(df)\n            <span class="kw">if</span> oran < kat_esik:\n                df[sut] = df[sut].<span class="fn">astype</span>(<span class="str">"category"</span>)\n        \n        <span class="kw">elif</span> np.<span class="fn">issubdtype</span>(sut_tur, np.integer):\n            df[sut] = pd.<span class="fn">to_numeric</span>(df[sut], downcast=<span class="str">"integer"</span>)\n        \n        <span class="kw">elif</span> np.<span class="fn">issubdtype</span>(sut_tur, np.floating):\n            df[sut] = pd.<span class="fn">to_numeric</span>(df[sut], downcast=<span class="str">"float"</span>)\n    \n    <span class="kw">return</span> df\n\n<span class="cm"># Kullanım</span>\ndf = pd.<span class="fn">read_csv</span>(<span class="str">"veri.csv"</span>)\nonce = df.<span class="fn">memory_usage</span>(deep=<span class="kw">True</span>).<span class="fn">sum</span>()\ndf = <span class="fn">dtype_optimize_et</span>(df)\nsonra = df.<span class="fn">memory_usage</span>(deep=<span class="kw">True</span>).<span class="fn">sum</span>()\n<span class="fn">print</span>(<span class="str">f"Azaltildi {önce/1e6:.1f} MB -> {sonra/1e6:.1f} MB"</span>)\n<span class="fn">print</span>(<span class="str">f"Tasarruf: {(1 - sonra/önce)*100:.0f}%"</span>)</code></pre></div>'

