+ 'var layout={title:{text:"Kumulatif Bellek Tasarrufu (1M Satır, 4 Sütun)",font:{color:"#ebe6dc",size:14}},paper_bgcolor:"rgba(0,0,0,0)",plot_bgcolor:"rgba(0,0,0,0)",font:{color:"#ebe6dc"},yaxis:{title:"Bellek (MB)",gridcolor:"rgba(255,255,255,0.06)",zerolinecolor:"rgba(255,255,255,0.15)"},xaxis:{gridcolor:"rgba(255,255,255,0.06)"},margin:{t:50,r:30,b:70,l:60},showlegend:false};'
+ 'Plotly.newPlot("plot-savings-tr",data,layout,{responsive:true,displayModeBar:false});'
